function pathFor(shape,phase=0){const n=32,points=[];for(let i=0;i<n;i++){const a=i/n*Math.PI*2;let r=28,sx=1,sy=1;if(shape.startsWith('soft-')){const k=Number(shape.slice(5));r=24+(2+k%6)*Math.cos(a*(3+k%7)+k*.4)+Math.sin(a*2+k)*1.2;sx=.82+(k%5)*.08;sy=.85+(k%4)*.1;}if(shape==='square')r=25/Math.pow(Math.pow(Math.abs(Math.cos(a)),5)+Math.pow(Math.abs(Math.sin(a)),5),.2);if(shape==='flower')r=27+5*Math.cos(a*6);if(shape==='star')r=26+7*Math.cos(a*5-Math.PI/2);if(shape==='fluff')r=27+3.2*Math.cos(a*10);if(shape==='blob')r=27+2*Math.cos(a*3)+Math.sin(a*5);if(shape==='ghost'){r=27+2*Math.cos(a*4);sy=1.15}if(shape==='pill'){r=27;sx=1.25;sy=.78}if(shape==='triangle')r=27+5*Math.cos((a+Math.PI/2)*3);if(shape==='leaf'){r=27+6*Math.sin(a);sx=.8;sy=1.08}if(shape==='moss')r=27+5*Math.cos(a*4);if(shape==='cloud'){r=27+3*Math.cos(a*3);sx=1.18;sy=.78}if(shape==='diamond')r=31/(Math.abs(Math.cos(a))+Math.abs(Math.sin(a)));if(shape==='ripple')r=27+3.5*Math.cos(a*8);if(shape==='clover')r=25+8*Math.cos(a*4);if(shape==='snow')r=26+7*Math.cos(a*6);if(shape==='drop'){r=27+7*Math.sin(a);sx=.88;sy=1.05}if(shape==='bean')r=27+5*Math.sin(a*2);if(shape==='moon'){r=27+4*Math.sin(a)+4*Math.cos(a*2);sx=.84;sy=1.1}if(shape==='gem')r=27/Math.cos(((a+Math.PI/6)%(Math.PI/3))-Math.PI/6);r+=Math.sin(a*3+phase)*1.4;let x=50+Math.cos(a)*r*sx,y=50+Math.sin(a)*r*sy;if(shape==='heart'){x=50+Math.pow(Math.sin(a),3)*29+Math.sin(phase)*.8;y=50-(13*Math.cos(a)-5*Math.cos(a*2)-2*Math.cos(a*3)-Math.cos(a*4))*1.7+Math.sin(a*3+phase)*.8}points.push([x,y])}const mid=(a,b)=>[(a[0]+b[0])/2,(a[1]+b[1])/2],start=mid(points.at(-1),points[0]);return'M'+start.map(x=>x.toFixed(2)).join(' ')+points.map((p,i)=>{const m=mid(p,points[(i+1)%n]);return'Q'+p.map(x=>x.toFixed(2)).join(' ')+' '+m.map(x=>x.toFixed(2)).join(' ')}).join('')+'Z'}
function dustArt(id,s=0,extra=''){const d=getDust(id),p=pathFor(d.shape),a=pathFor(d.shape,1.5),b=pathFor(d.shape,3),mouth=d.shape==='square'?'M46 59Q50 54 54 59':s===0?'M47 58Q50 61 53 58':'M45 57Q50 63 55 57',openEye=(x)=>`<ellipse cx="${x}" cy="48" rx="2.5" ry="3.6"/>`,closedEye=(x)=>`<path d="M${x-3} 48Q${x} 51 ${x+3} 48" fill="none" stroke="${d.face}" stroke-width="2.2" stroke-linecap="round"/>`,eyes=d.expression==='sleepy'?closedEye(41)+closedEye(59):d.expression==='wink'?openEye(41)+closedEye(59):openEye(41)+openEye(59);return `<span class="dust-art ${extra}" role="img" aria-label="${d.name} ${STAGES[s]}" style="--dust-color:${d.color};--dust-face:${d.face}"><svg viewBox="0 0 100 100" aria-hidden="true"><g class="dust-body"><path d="${p}" fill="${d.color}">${reduced.matches?'':`<animate attributeName="d" dur="3.2s" values="${p};${a};${b};${p}" repeatCount="indefinite"/>`}</path>${d.expression==='shy'?`<g fill="${d.face}" opacity=".18"><ellipse cx="35" cy="55" rx="4" ry="2"/><ellipse cx="65" cy="55" rx="4" ry="2"/></g>`:''}${d.shape==='moon'?'<path d="M54 28A6 6 0 1 0 60 36A6 6 0 0 1 54 28" fill="#f0e7c8" opacity=".7"/>':''}<g class="dust-eyes" fill="${d.face}">${eyes}</g>${d.expression==='surprised'?`<ellipse cx="50" cy="59" rx="2.5" ry="3.2" fill="${d.face}"/>`:`<path class="dust-mouth" d="${mouth}" stroke="${d.face}" stroke-width="2.6" fill="none" stroke-linecap="round"/>`}</g></svg></span>`}
