function openMix(preset=null){if(!state.pending)selection=preset?{...preset}:{group:'',rarity:'',essence:''};modal('작은 빛에서 태어나는 친구.',`<div id="mixContent">${mixContent()}</div>`);mixDialogOpen=true;$('.modal-card').classList.add('mix-dialog');}
