function renderCollection(){const c=counts();return heading('소중히 모은 친구들','작지만, 하나하나 달라요.','같은 먼지도 한 마리씩 자라고 있어요.')+`<div class="collection-summary"><span>발견 <b>${c.types}</b> / ${DUSTS.length}종</span><span>전체 <b>${c.total}</b>마리</span><span>포근해진 먼지 <b>${c.grown}</b>마리</span></div><div class="dust-grid">${DUSTS.map((d,i)=>{const all=copies(d.id),s=all.length?Math.max(...all.map(x=>stage(x.xp))):0;return `<button class="dust-card ${all.length?'':'undiscovered'}" data-detail="${d.id}"><span class="card-num">${String(i+1).padStart(2,'0')}</span><span class="card-count">${all.length}마리</span>${dustArt(d.id,s)}<h2>${all.length?d.name:'아직 모르는 먼지'}</h2><p>${find(GROUPS,d.group).name} · ${find(RARITIES,d.rarity).name}</p></button>`}).join('')}</div>`}

function renderStorage(){const all=state.dusts.filter(d=>d.stored);return heading('잠시 쉬어가는 곳','작은 보관함.','레벨과 이야기를 그대로 품고 쉬고 있어요.')+`<div class="storage-note"><span>보관한 먼지 <b>${all.length}</b> / ${storageCapacity(state)}마리</span><small>꺼내면 이어서 키울 수 있어요.</small></div>${all.length?`<div class="storage-grid">${all.map(d=>{const info=getDust(d.id),num=copies(d.id).findIndex(x=>x.uid===d.uid)+1;return `<article class="storage-card">${dustArt(d.id,stage(d.xp))}<div><h2>${info.name}${copies(d.id).length>1?' #'+num:''}</h2><p>Lv.${level(d.xp)} · ${STAGES[stage(d.xp)]}</p><span class="storage-story-count">이야기 ${unlockedStories(d)} / 5</span></div><div class="storage-actions"><button class="text-button" data-story="${d.uid}">이야기 읽기</button><button class="button yellow" data-take-out="${d.uid}">꺼내서 키우기 →</button></div></article>`}).join('')}</div>`:'<div class="empty-storage"><span>◌</span><h2>아직 쉬고 있는 먼지가 없어요.</h2><p>먼지의 방에서 ‘보관하기’를 눌러보세요.<br>모든 성장 기록은 그대로 남아요.</p><button class="button secondary" data-page="room">먼지의 방으로 →</button></div>'}`;}
