function rubMove(event){
 if(roomDrag?.active){rubTrack=null;return;}
 if(page!=='room'||!$('#modal').classList.contains('hidden')){rubTrack=null;return;}
 const button=event.target.closest?.('.room-dust');if(!button){rubTrack=null;return;}
 if(event.pointerType==='touch'&&!event.buttons){rubTrack=null;return;}
 const uid=Number(button.dataset.dust),dust=state.dusts.find(d=>d.uid===uid);if(!dust||dust.stored){rubTrack=null;return;}
 const rect=button.getBoundingClientRect(),threshold=24;
 rubTrack=trackRub(rubTrack,{uid,pointerId:event.pointerId,x:event.clientX,y:event.clientY,time:event.timeStamp,inside:bodyContains(button,event.clientX,event.clientY)},threshold);
 if(!rubTrack?.moved)return;
 suppressDustClickUntil=Date.now()+400;
 let earned=false;if(rubTrack.reached){const result=pet(state,Date.now(),uid);if(result.ok){earned=result.amount;rubTrack.distance=0;$('#sparkles').textContent=state.sparkles;save();}}
 showRub(uid,rubTrack.distance/threshold,earned);
}
document.addEventListener('pointermove',rubMove);
document.addEventListener('pointerdown',event=>{const button=event.target.closest?.('.room-dust');if(button&&event.pointerType==='touch'){button.setPointerCapture(event.pointerId);rubTrack=null;}});
document.addEventListener('pointerup',event=>{if(event.pointerType==='touch')rubTrack=null;});
document.addEventListener('pointercancel',()=>{rubTrack=null;});

function render(){const c=counts();renderHeader();$('#sparkles').textContent=state.sparkles;$('#gold').textContent=state.gold;$('#collectionCount').textContent=c.types;$('#storageCount').textContent=c.stored;$('#main').innerHTML=page==='room'?renderRoom():page==='mix'?renderMix():page==='shop'?renderShop():page==='storage'?renderStorage():renderCollection();document.querySelectorAll('.navigation button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));tick(false)}
function go(next){if(next==='mix')return openMix();close();page=next;render();window.scrollTo({top:0,behavior:'smooth'})}
function modal(title,html,after){roomDialogOpen=false;adventureDialogOpen=false;mixDialogOpen=false;lastFocus=document.activeElement;$('#modal').innerHTML=`<div class="modal-card"><button class="close" aria-label="닫기">×</button><span class="kicker">작고 소중한 먼지</span><h2 id="modalTitle">${title}</h2>${html}</div>`;$('#modal').classList.remove('hidden');document.body.style.overflow='hidden';$('.close').onclick=close;$('#modal').onclick=e=>{if(e.target===$('#modal'))close()};$('.close').focus();after?.()}
function close(){roomDialogOpen=false;adventureDialogOpen=false;mixDialogOpen=false;$('#modal').classList.add('hidden');$('#modal').innerHTML='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus()}
function makeHappy(uid){happyUid=uid;clearTimeout(happyTimer);render();happyTimer=setTimeout(()=>{happyUid=null;$('.room-dust.happy')?.classList.remove('happy')},1800)}
function feedDust(){const current=selected();if(!current)return toast('보관함에서 먼지를 먼저 꺼내주세요.');const r=feed(state,current.uid);if(!r.ok)return toast(r.message);save();makeHappy(r.dust.uid);if(r.leveled){const d=getDust(r.dust.id),chapter=STORIES[d.id][r.chapter];modal('Lv.'+level(r.dust.xp)+' · 새 이야기가 열렸어요.',`${dustArt(d.id,stage(r.dust.xp))}<span class="new-badge">이야기 ${r.chapter+1} / 5</span><h3 class="unlocked-story-title">${chapter.title}</h3><p>${r.grew?STAGES[stage(r.dust.xp)]+'로 자랐어요.<br>':''}${d.name}의 이야기를 한 편 더 읽을 수 있어요.</p><button class="button yellow full" data-chapter="${r.dust.uid}:${r.chapter}">새 이야기 읽기 →</button><button class="text-button read-later" id="readLater">나중에 읽을게요</button>`,()=>$('#readLater').onclick=close)}else toast(r.refunded?'러그 덕분에 반짝이 1개를 돌려받았어요.':'반짝이를 냠. 다음 레벨까지 1개 남았어요.');}

function showMaterials(){modal('작은 재료 가방',`<p>조합할 때 그룹 1개 + 희귀도 1개 + 정수를 써요.<br>먼지를 모험에 보내면 재료를 모아 돌아와요.</p>${[['group',GROUPS,'그룹'],['rarity',RARITIES,'희귀도'],['essence',ESSENCES,'정수']].map(([key,items,label])=>`<div class="material-set"><h3>${label}</h3><div>${items.map(x=>`<span>${icon(x.id)}${x.name}<b>${state.materials[key][x.id]}</b></span>`).join('')}</div></div>`).join('')}<button class="button secondary full" data-shop-materials>골드로 재료 사기 ↗</button><button class="button yellow full" data-open-adventure>작은 모험으로 재료 모으기 ↗</button><button class="text-button return-mix" id="returnMix">조합 팝업으로 돌아가기 ↗</button>`,()=>{$('#returnMix').onclick=()=>openMix(selection)})}
function detail(id){const d=getDust(id),all=copies(id),max=all.length?Math.max(...all.map(x=>stage(x.xp))):-1;modal(all.length?d.name:'아직 만나지 못했어요.',`${dustArt(id,Math.max(0,max),all.length?'':'silhouette')}<div class="detail-tags"><span>${find(GROUPS,d.group).name}</span><span>${find(RARITIES,d.rarity).name}</span><span>보유 ${all.length}마리</span></div><p>${all.length?d.story:'아래 조합법으로 먼지를 데려와 보세요.'}</p><div class="growth-pair trio">${STAGES.map((name,i)=>`<div class="${max>=i?'':'unseen'}">${dustArt(id,i)}<span>${name}</span><small>${i===0?'처음 만났을 때':i===1?'반짝이 2개':'반짝이 6개'}</small></div>`).join('')}</div>${all.length?`<div class="copies">${all.map((v,i)=>`<div class="copy-row"><button data-copy="${v.uid}"><span style="background:${d.color}"></span>${d.name}${all.length>1?' #'+(i+1):''}<small>Lv.${level(v.xp)} · ${v.stored?'보관 중':isAway(state,v.uid)?'모험 중':STAGES[stage(v.xp)]}</small></button><button class="copy-story" data-story="${v.uid}" aria-label="${d.name} ${i+1} 이야기">▤</button><button class="copy-store" ${v.stored?'data-take-out':'data-store'}="${v.uid}">${v.stored?'꺼내기':'보관'}</button></div>`).join('')}</div>`:''}<button class="button yellow full" id="detailMix">${all.length?'같은 먼지 한 마리 더':'이 먼지 만나러 가기'} →</button>`,()=>$('#detailMix').onclick=()=>{close();openMix({group:d.group,rarity:d.rarity,essence:d.essence})})}
function tick(finish=true){updateGoldUI();updateAdventureUI();if(finish&&state.pending){const r=finishMix(state);if(r){save();render();const d=getDust(r.dust.id);modal(r.isNew?'안녕, '+d.name+'!':'반가워, '+d.name+'.',`${dustArt(d.id,0)}<p>“${d.quote}”</p><span class="new-badge">${r.mode==='random'?'빛에서 우연히 만났어요':'재료 조합으로 만났어요'} · ${r.isNew?'새로운 종류 발견':'보유 '+copies(d.id).length+'마리'}</span><button class="button yellow full" id="welcome">${r.dust.stored?'보관함에서 만나기':'우리 방으로 데려가기'}</button>${r.dust.stored?'<p>방이 가득 차서 보관함에서 쉬고 있어요.</p>':''}`,()=>$('#welcome').onclick=()=>{close();go(r.dust.stored?'storage':'room')})}}}
function guide(){modal('먼지는 이렇게 자라요.',`<div class="guide-list"><p><b>↔ 먼지와 가구 옮기기</b>몸이나 가구를 0.5초 정도 길게 누른 뒤 끌어주세요.<br>원하는 곳에 놓으면 위치가 저장돼요.<br>키보드는 선택 후 Alt + 방향키로 옮길 수 있어요.</p><p><b>◉ 먼지가 모아주는 골드</b>먼지마다 20~167초에 한 번 골드가 준비돼요.<br>머리 위 골드를 눌러 받아요.<br>상점에서 요정 모아를 데려오면 방에 찾아와요.<br>방의 모아를 누르거나 상점에서 한 번에 받을 수 있어요.<br>접속을 쉬어도 먼지당 한 번의 보상을 보관해요.<br>수령하면 시간이 다시 시작되고 보관함에서는 멈춰요.</p><p><b>⌂ 방과 작은 가구</b>골드로 방을 업그레이드하면 보상과 방·보관함 자리가 늘어요.<br>방 이름을 누르면 다음 방과 이야기를 볼 수 있어요.<br>상점에서 가구를 사서 놓으면 표시된 효과가 적용돼요.<br>가구는 Lv.5까지 자라고 단계마다 이야기가 열려요.<br>넣어둔 가구는 효과가 멈추고 다시 무료로 놓을 수 있어요.<br>재료도 골드로 살 수 있어요.</p><p><b>✧ 반짝이를 냠냠</b>반짝이 하나를 주면 1만큼 자라요.<br>2번 주면 몽글 먼지, 6번 주면 포근 먼지가 돼요.</p><p><b>▤ 레벨마다 열리는 이야기</b>반짝이 2개마다 레벨이 올라요.<br>Lv.2부터 Lv.6까지 한 편씩, 총 5편을 읽을 수 있어요.</p><p><b>◌ 잠시 보관하기</b>방의 ‘보관하기’로 쉬게 해주세요.<br>하단 ‘보관함’에서 꺼내면 레벨과 이야기가 이어져요.</p><p><b>♡ 살짝 쓰다듬기</b>먼지 몸 위에서 커서를 왔다 갔다 움직여주세요.<br>문지르면 반짝이가 머리 위 말풍선에 쌓이고 바로 보유량에 더해져요.<br>터치 화면에서는 손가락으로 쓸어줄 수 있어요.</p><p><b>+ 새로운 먼지 만나기</b>방의 빛나는 곳을 눌러 팝업을 열어요.<br>세 재료를 조합하면 정해진 먼지, 모두 비우면 랜덤한 먼지가 태어나요.<br>같은 먼지가 와도 각각 따로 자라요.</p><p><b>⚑ 작은 모험</b>모험 관리인 루미를 눌러 목적지를 골라요.<br>먼지를 길게 눌러 루미 앞으로 옮기면 모험을 떠나요.<br>루미를 다시 누르면 모험 소식과 돌아온 선물을 확인해요.<br>모험 중에는 돌보기·보관·골드 생산을 잠시 쉬어요.<br>창을 닫아도 모험은 계속되고 보상은 한 번만 받을 수 있어요.</p></div><button class="button yellow full" id="guideDone">먼지 보러 가기</button><button class="text-button return-mix" id="guideBack">작은 기록으로 돌아가기</button>`,()=>{$('#guideDone').onclick=close;$('#guideBack').onclick=settings;})}
function settings(){modal('작은 기록',`<p>${counts().types}종 · ${state.dusts.length}마리의 먼지와 함께하고 있어요.<br>기록은 이 브라우저에 자동 저장돼요.</p><button class="record-help" id="guide"><span>?</span><b>어떻게 키워요?</b><i>↗</i></button><div class="save-buttons"><button class="button secondary" id="export">기록 내보내기</button><label class="button secondary">기록 가져오기<input id="import" type="file" accept=".json,application/json"></label></div><button class="text-button reset" id="reset">새로운 방에서 시작</button>`,()=>{$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='my-little-dusts.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('작은 기록을 저장했어요.')};$('#import').onchange=async e=>{try{state=restore(await e.target.files[0].text());save();close();go('room');toast('먼지들이 돌아왔어요.')}catch{toast('이 게임에서 내보낸 저장 파일을 골라주세요.')}};$('#reset').onclick=()=>modal('새로운 방으로 갈까요?',`<p>지금 모은 먼지와 재료가 초기화돼요.<br>필요하다면 먼저 기록을 내보내주세요.</p><button class="button yellow full" id="confirmReset">새로 시작하기</button><button class="button secondary full" id="cancelReset">돌아가기</button>`,()=>{$('#confirmReset').onclick=()=>{state=createState();save();close();go('room')};$('#cancelReset').onclick=settings})})}
document.addEventListener('click',e=>{if(Date.now()<suppressRoomClickUntil)return;const b=e.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-open-rooms'))openRooms();else if(b.dataset.roomStory)roomStory(Number(b.dataset.roomStory)-1);else if(b.dataset.upgradeFurniture){const r=upgradeFurniture(state,b.dataset.upgradeFurniture);if(!r.ok)return toast(r.message);save();render();toast('Lv.'+r.level+' · 가구의 새 이야기가 열렸어요.');}else if(b.dataset.furnitureStory){const [id,index]=b.dataset.furnitureStory.split(':');furnitureBook(id,Number(index)||0);}else if(b.id==='buyFairy'){const r=buyFairy(state);if(!r.ok)return toast(r.message);save();render();toast('요정 모아가 방에 찾아왔어요. 모아를 눌러 골드를 모두 받아요.');}else if(b.id==='fairyCollect')earnGold();else if(b.dataset.collectGold)earnGold(Number(b.dataset.collectGold));else if(b.dataset.shopTab){shopTab=b.dataset.shopTab;render()}else if(b.hasAttribute('data-shop-materials')){shopTab='materials';go('shop')}else if(b.hasAttribute('data-upgrade-room')){const r=upgradeRoom(state);if(!r.ok)return toast(r.message);save();render();refreshRooms();toast('Lv.'+state.roomLevel+' · '+ROOMS[state.roomLevel-1].name+'이 되었어요. 방 이야기도 열렸어요.')}else if(b.dataset.furniture){const r=toggleFurniture(state,b.dataset.furniture);if(!r.ok)return toast(r.message);save();render();toast(r.placed?'가구를 놓았어요. 효과가 적용돼요.':'가구를 넣어두었어요. 언제든 다시 놓을 수 있어요.')}else if(b.dataset.buyMaterial){const [key,id]=b.dataset.buyMaterial.split(':');const r=buyMaterial(state,key,id);if(!r.ok)return toast(r.message);save();render();toast('재료 1개를 가방에 넣었어요.')}else if(b.hasAttribute('data-open-storage'))openStorage();else if(b.dataset.store)archiveDust(Number(b.dataset.store));else if(b.dataset.takeOut)bringBack(Number(b.dataset.takeOut));else if(b.dataset.story)storyBook(Number(b.dataset.story));else if(b.dataset.storyList)storyList(Number(b.dataset.storyList));else if(b.dataset.chapter){const [uid,index]=b.dataset.chapter.split(':').map(Number);storyBook(uid,index)}else if(b.dataset.page)go(b.dataset.page);else if(b.dataset.dust){if(e.detail>1||Date.now()<suppressDustClickUntil)return;focusRoomDust(Number(b.dataset.dust))}else if(b.dataset.detail)detail(b.dataset.detail);else if(b.dataset.copy){const d=state.dusts.find(x=>x.uid===Number(b.dataset.copy));if(d&&isAway(state,d.uid)){openAdventures();return;}if(d?.stored)bringBack(d.uid);else if(d){state.selectedUid=d.uid;save();close();go('room')}}else if(b.dataset.recipe){const d=getDust(b.dataset.recipe);selection={group:d.group,rarity:d.rarity,essence:d.essence};if(mixDialogOpen){refreshMix();$('.modal-card').scrollTo({top:0,behavior:'smooth'})}else openMix(selection)}else if(b.id==='glowTrigger')openMix();else if(b.id==='clearMix'){selection={group:'',rarity:'',essence:''};refreshMix()}else if(b.id==='feed')feedDust();else if(b.hasAttribute('data-open-adventure')||b.id==='adventureDoor')openAdventures();else if(b.dataset.keeperRoute){chooseKeeperRoute(state,b.dataset.keeperRoute);save();render();refreshAdventures();}else if(b.dataset.claimQuest)receiveAdventure(Number(b.dataset.claimQuest));else if(b.id==='materials')showMaterials();else if(b.id==='summon'){const r=mix(state,selection);if(r.ok){save();render();refreshMix()}else toast(r.message)}else if(b.id==='settings')settings();else if(b.id==='guide')guide()});
document.addEventListener('change',e=>{if(e.target.id==='questDust'){questDustUid=Number(e.target.value);refreshAdventures();return;}if(e.target.dataset.pick){selection[e.target.dataset.pick]=e.target.value;refreshMix(e.target.id)}});$('#home').onclick=e=>{e.preventDefault();go('room')};document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&!$('#modal').classList.contains('hidden')){const nodes=[...$('#modal').querySelectorAll('button,input,select,summary')].filter(n=>!n.disabled&&n.offsetParent!==null),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault()}}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick()});render();save();setInterval(tick,300);


function roomDecor(){return `<div class="room-decor" aria-label="놓아둔 가구">${state.decorations.map(id=>{const p=state.roomPositions.furniture[id]||DEFAULT_DECOR[id];return `<span class="decor decor-${id}" data-room-item="furniture" data-room-id="${id}" role="button" tabindex="0" aria-label="${FURNITURE.find(f=>f.id===id).name} · 길게 눌러 이동" style="left:${p.x}%;top:${p.y}%;right:auto;bottom:auto;translate:-50% -50%">${furnitureArt(id,furnitureLevel(state,id))}</span>`;}).join('')}</div>`;}
function goldBubble(d){return goldReady(state,d)?`<button class="gold-bubble" data-collect-gold="${d.uid}" aria-label="${getDust(d.id).name} 골드 ${goldAmount(state,d)} 받기">${icon('coin')}<b>+${goldAmount(state,d)}</b></button>`:'';}
function selectedIncome(d){return `<div class="income-strip"><span>${icon('coin')}<b>${getDust(d.id).name}의 작은 보답</b></span><span>매 ${goldInterval(state,d)/1000}초 · ${goldAmount(state,d)} 골드</span><strong id="selectedGoldTimer"></strong></div>`;}
function updateGoldUI(){
 const now=Date.now(),ready=state.dusts.filter(d=>goldReady(state,d,now)),sum=ready.reduce((a,d)=>a+goldAmount(state,d),0);
 document.querySelectorAll('[data-gold-slot]').forEach(el=>{const d=state.dusts.find(x=>x.uid===Number(el.dataset.goldSlot));if(!d)return;const reward=goldReady(state,d,now)?String(goldAmount(state,d)):'';if(el.dataset.reward!==reward){el.innerHTML=goldBubble(d);el.dataset.reward=reward;}});
 const status=$('#roomGoldStatus');if(status)status.textContent=ready.length?`${ready.length}마리 · ${sum} 골드 준비됐어요`:'골드가 모이는 중';const fairy=$('#fairyCollect');if(fairy){fairy.disabled=!ready.length;fairy.setAttribute('aria-label',ready.length?`요정 모아 · ${sum} 골드 모두 받기`:'요정 모아 · 골드가 모이는 중');$('#fairyStatus').textContent=ready.length?`${sum} 골드 모두 받기`:'골드가 모이는 중';}
 const d=selected(),timer=$('#selectedGoldTimer');if(d&&timer)timer.textContent=goldReady(state,d,now)?'받을 수 있어요!':Math.max(0,Math.ceil((d.goldAt-now)/1000))+'초 뒤에 만나요';
}
function earnGold(uid=null){const r=uid===null?collectAllGold(state):collectGold(state,uid);if(!r.ok)return toast(r.message||'아직 골드가 모이는 중이에요.');save();$('#gold').textContent=state.gold;$('#sparkles').textContent=state.sparkles;if($('.shop-balance>b'))$('.shop-balance>b').innerHTML=state.gold.toLocaleString()+' <small>골드</small>';updateGoldUI();toast('작은 보답, '+r.amount+' 골드'+(r.sparkles?'와 반짝이 '+r.sparkles+'개':'')+'를 받았어요.');}
function renderShop(){const room=ROOMS[state.roomLevel-1],next=ROOMS[state.roomLevel],count=state.decorations.length;return heading('조금씩 더 포근하게','작은 먼지의 살림.','먼지가 모아준 골드로 방과 재료를 준비해요.')+`<div class="shop-balance">${icon('coin')}<b>${state.gold.toLocaleString()} <small>골드</small></b><span>먼지의 방에서 골드를 모을 수 있어요.</span></div><section class="upgrade-card" style="--room-color:${room.color}"><div class="upgrade-house"><span>⌂</span><b>Lv.${state.roomLevel}</b></div><div><span class="shop-eyebrow">지금 우리 방</span><h2>${room.name}</h2><p>골드 +${room.bonus}% · 방 ${room.capacity}자리 · 보관함 ${room.storage}자리</p>${next?`<small>다음 방: ${next.name} · 골드 보상 +${next.bonus}%</small>`:'<small>가장 포근한 방을 완성했어요.</small>'}</div><div class="room-upgrade-actions"><button class="button yellow" data-upgrade-room ${!next||state.gold<next.cost?'disabled':''}>${next?`${next.cost} 골드로 업그레이드`:'최고 레벨'}</button><button class="text-button open-room-list" data-open-rooms>방 목록과 이야기 보기 ↗</button></div></section>${fairyShopCard()}<div class="collection-tabs shop-tabs"><button data-shop-tab="furniture" class="${shopTab==='furniture'?'active':''}">방 꾸미기</button><button data-shop-tab="materials" class="${shopTab==='materials'?'active':''}">조합 재료</button></div>${shopTab==='furniture'?`<p class="shop-note">사서 놓으면 방 전체에 효과가 적용돼요. 넣어두었다가 무료로 다시 놓을 수 있어요.</p><div class="furniture-grid">${FURNITURE.map(furnitureCard).join('')}</div>`:`<p class="shop-note">필요한 만큼 한 개씩 살 수 있어요. 구매한 재료는 조합 팝업에서 바로 쓸 수 있어요.</p>${[['group',GROUPS,'그룹'],['rarity',RARITIES,'희귀도'],['essence',ESSENCES,'정수']].map(([key,items,title])=>`<section class="shop-materials"><h2>${title}</h2><div>${items.map(x=>{const price=materialPrice(key,x.id);return `<article class="material-card">${icon(x.id)}<h3>${x.name}</h3><p>보유 ${state.materials[key][x.id]}개</p><button class="button secondary" data-buy-material="${key}:${x.id}" ${state.gold<price?'disabled':''}>${price} 골드 · 1개</button></article>`;}).join('')}</div></section>`).join('')}<button class="button yellow full" data-page="mix">재료 조합하러 가기 →</button>`}`;}

function dustProgress(d){return `<div class="header-dust-name"><span class="tiny-dot" style="background:${getDust(d.id).color}"></span><b>${getDust(d.id).name}</b><small>Lv.${level(d.xp)} · ${STAGES[stage(d.xp)]}</small></div><div class="header-growth-label"><span>${d.xp>=10?'모든 이야기를 모았어요':'다음 레벨까지 반짝이 '+(2-d.xp%2)+'개'}</span><b>${d.xp>=10?'MAX':d.xp%2+' / 2'}</b></div><div class="growth-track"><i style="width:${d.xp>=10?100:d.xp%2*50}%;background:${getDust(d.id).color}"></i></div>`;}
function renderHeader(){const c=counts();$('#headerCounts').innerHTML=`<span class="resource-count" title="발견한 먼지" aria-label="발견한 먼지 ${c.types} / ${DUSTS.length}">${icon('catalog')}<b>${String(c.types).padStart(2,'0')}<em>/${DUSTS.length}</em></b><small data-short="발견">발견한 먼지</small></span><span class="resource-count" title="방 ${homeCount(state)}자리 사용 (모험 중 포함) / 최대 ${roomCapacity(state)}자리" aria-label="방에 있는 먼지 ${c.active} / 최대 ${roomCapacity(state)}">${icon('residents')}<b>${String(c.active).padStart(2,'0')}<em>/${String(roomCapacity(state)).padStart(2,'0')}</em></b><small data-short="방">방에 있는 먼지</small></span>`;}

function careDock(active){const d=getDust(active.id);return `<section class="care-dock care-panel"><div class="care-main"><div class="care-identity">${dustArt(active.id,stage(active.xp))}<div><span class="care-eyebrow">지금 함께하는 먼지</span><h2>${d.name}<small>Lv.${level(active.xp)}</small></h2><p>${STAGES[stage(active.xp)]} · ${find(RARITIES,d.rarity).name}</p></div></div><div class="care-growth"><div class="header-growth-label"><span>${active.xp>=10?'모든 이야기를 모았어요':'다음 레벨까지 반짝이 '+(2-active.xp%2)+'개'}</span><b>${active.xp>=10?'MAX':active.xp%2+' / 2'}</b></div><div class="growth-track"><i style="width:${active.xp>=10?100:active.xp%2*50}%;background:${d.color}"></i></div><small>열린 이야기 ${unlockedStories(active)} / 5</small></div><div class="care-feed"><button class="button yellow" id="feed" ${active.xp>=10?'disabled':''}>✧ 반짝이 주기 <small>1</small></button><span>먼지 위에서 커서를 움직여 모아요.</span></div></div><div class="care-bottom">${selectedIncome(active)}${storyActions(active)}</div></section>`;}
function storyActions(active){return `<div class="under-room story-actions"><button class="text-button" data-detail="${active.id}">성장 모습 ↗</button><button class="text-button story-link" data-story="${active.uid}">▤ 이야기 ${unlockedStories(active)}/5 ${unlockedStories(active)>active.readStories.length?'<i class="unread-dot"></i>':''}</button><button class="text-button" data-store="${active.uid}">보관하기</button></div>`;}

function focusRoomDust(uid){
 if(!selectDust(state,uid))return;
 save();renderHeader();const active=selected();
 document.querySelectorAll('.room-dust').forEach(el=>{const on=Number(el.dataset.dust)===uid;el.classList.toggle('selected',on);el.setAttribute('aria-pressed',String(on));const bubble=el.querySelector('.rub-bubble');if(bubble&&!bubble.classList.contains('show'))bubble.classList.toggle('hint',on);});
 const care=$('.care-dock');if(care)care.outerHTML=careDock(active);updateGoldUI();
}
function adventureDoor(){return `<button class="adventure-keeper" id="adventureDoor" aria-label="모험 관리인 루미 · 모험 중인 먼지 보기"><span class="keeper-gate" aria-hidden="true">${icon('residents')}</span><span class="keeper-character">${icon('keeper')}</span><b>모험 관리인 루미</b><small>${find(QUESTS,state.keeperRoute).name}</small><span id="adventureDoorStatus">먼지를 이곳으로 ↗</span></button>`;}
function rewardChips(route){return `<div class="quest-rewards">${route.rewards.map(([key,id,amount])=>{const item=find({group:GROUPS,rarity:RARITIES,essence:ESSENCES}[key],id);return `<span>${icon(id)}<b>${item.name}</b><small>×${amount+(key==='essence'?activeLevel(state,'basket'):0)}</small></span>`;}).join('')}<span class="quest-sparkles">✧ <b>반짝이</b><small>×${route.sparkles}</small></span></div>`;}
function adventureContent(){return `<p class="adventure-intro">루미가 모험 중인 친구들을 지켜보고 있어요.<br>목적지를 고르고 먼지를 길게 눌러 관리인 앞으로 옮겨주세요.</p>${state.adventures.length?`<section class="travelers"><h3>모험 소식 <small>${state.adventures.length}마리</small></h3>${state.adventures.map(q=>{const d=state.dusts.find(x=>x.uid===q.uid),route=find(QUESTS,q.route);return `<article class="traveler" data-traveler="${q.uid}" style="--route-color:${route.color}"><div class="traveler-heading"><b>${getDust(d.id).name}</b><span>${route.name}</span><small data-quest-time="${q.uid}"></small></div><div class="travel-scene"><span class="travel-home">⌂</span><i class="travel-path"></i><span class="travel-dust">${dustArt(d.id,stage(d.xp))}</span><span class="travel-flag">⚑</span></div><button class="button secondary full" data-claim-quest="${q.uid}" disabled>모험 중이에요</button></article>`;}).join('')}</section>`:''}<section class="quest-planning"><h3>다음 모험의 목적지</h3><div class="quest-routes">${QUESTS.map((route,i)=>`<article class="quest-route ${state.keeperRoute===route.id?'chosen':''}" style="--route-color:${route.color}"><div class="route-title"><span class="route-number">0${i+1}</span><div><h4>${route.name}</h4><p>${route.description}</p></div><small>${Math.round(route.duration*(1-activeLevel(state,'windchime')*.05))/1000}초</small></div>${rewardChips(route)}<button class="button ${state.keeperRoute===route.id?'secondary':'yellow'} full" data-keeper-route="${route.id}" ${state.keeperRoute===route.id?'disabled':''}>${state.keeperRoute===route.id?'지금 이 길로 안내하고 있어요':'이 길로 안내하기 →'}</button></article>`).join('')}</div></section><p class="quest-footnote">루미 앞에 먼지를 놓으면 바로 모험을 떠나요.<br>모험 중에는 쓰다듬기·성장·보관·골드 생산을 쉬어요.<br>돌아오면 루미를 눌러 재료 선물을 받아주세요.</p>`;}
function openAdventures(){questDustUid=state.selectedUid;modal('관리인 루미의 모험 수첩.',`<div id="adventureContent">${adventureContent()}</div>`);adventureDialogOpen=true;$('.modal-card').classList.add('adventure-dialog');updateAdventureUI();}
function refreshAdventures(){if(!adventureDialogOpen)return;$('#adventureContent').innerHTML=adventureContent();updateAdventureUI();}
function updateAdventureUI(){
 const now=Date.now(),ready=state.adventures.filter(q=>q.end<=now).length,door=$('#adventureDoorStatus');if(door)door.textContent=ready?`${ready}마리 돌아왔어요!`:state.adventures.length?`${state.adventures.length}마리 모험 중`:'먼지를 이곳으로 ↗';
 if(!adventureDialogOpen)return;
 for(const q of state.adventures){const card=document.querySelector(`[data-traveler="${q.uid}"]`);if(!card)continue;const complete=q.end<=now,progress=Math.max(0,Math.min(1,(now-q.start)/(q.end-q.start)));card.style.setProperty('--travel-progress',String(progress));card.classList.toggle('returned',complete);card.querySelector('[data-quest-time]').textContent=complete?'돌아왔어요!':Math.ceil((q.end-now)/1000)+'초 남음';const button=card.querySelector('[data-claim-quest]');button.disabled=!complete;button.textContent=complete?'돌아온 먼지 맞이하고 선물 받기':'모험 중이에요';}
}
function sendAdventure(route){const r=startAdventure(state,questDustUid,route);if(!r.ok)return toast(r.message);save();render();refreshAdventures();toast('작은 배낭을 메고 모험을 떠났어요.');}
function receiveAdventure(uid){const r=claimAdventure(state,uid);if(!r.ok)return toast(r.message);save();render();modal(getDust(r.dust.id).name+'가 돌아왔어요!',`<div class="returned-dust">${dustArt(r.dust.id,stage(r.dust.xp))}</div><p>${r.route.name}에서 소중한 재료를 모아왔어요.</p>${rewardChips(r.route)}<button class="button yellow full" data-open-adventure>다른 모험 확인하기 ↗</button><button class="text-button return-mix" data-page="room">같이 방에서 쉬기 →</button>`);}
document.addEventListener('dblclick',event=>{if(event.target.closest?.('.room-dust'))event.preventDefault();});

function roomPlaque(){return `<button class="room-plaque" data-open-rooms aria-label="${ROOMS[state.roomLevel-1].name} · 방 목록과 이야기"><span class="plaque-house">⌂</span><span><b>Lv.${state.roomLevel} · ${ROOMS[state.roomLevel-1].name}</b><small>골드 +${ROOMS[state.roomLevel-1].bonus}% · 방 ${homeCount(state)}/${roomCapacity(state)} <i>·</i> <span id="roomGoldStatus">골드가 모이는 중</span></small></span><i class="plaque-arrow">↗</i></button>`;}

function fairyShopCard(){return `<section class="fairy-shop-card ${state.fairyOwned?'has-fairy':''}"><div class="fairy-portrait">${icon('fairy')}</div><div><span class="effect-badge">골드 한 번에 받기</span><h2>골드 모으는 요정, 모아</h2><p>모아에게 부탁하면 준비된 골드를 모두 받아요.<br>데려온 뒤에는 방에서도 모아를 눌러 한 번에 받아요.</p></div>${state.fairyOwned?'<button class="button yellow" id="fairyCollect"><span id="fairyStatus">골드 모두 받기</span></button>':`<button class="button yellow" id="buyFairy" ${state.gold<FAIRY_PRICE?'disabled':''}>${FAIRY_PRICE} 골드 · 요정 데려오기</button>`}</section>`;}

function setItemAnchor(el,x,y){el.style.left=x+'%';el.style.top=y+'%';const gold=el.dataset.roomItem==='dust'?document.querySelector(`[data-gold-slot="${el.dataset.roomId}"]`):null;if(gold){gold.style.left=x+'%';gold.style.top=y+'%';gold.style.animation='none';}}
function clearMoveReady(){if(moveReady)moveReady.classList.remove('move-ready');moveReady=null;}
function activateRoomDrag(drag){
 if(roomDrag!==drag||!drag.el.isConnected)return;
 clearMoveReady();moveReady=drag.el;drag.active=true;rubTrack=null;drag.el.classList.remove('rubbing');drag.el.classList.add('move-ready','moving-item');
 const box=drag.el.getBoundingClientRect(),room=drag.room.getBoundingClientRect();drag.offsetX=box.x+box.width/2-drag.x;drag.offsetY=box.y+box.height/2-drag.y;
 drag.el.style.animation='none';setItemAnchor(drag.el,(box.x+box.width/2-room.x)/room.width*100,(box.y+box.height/2-room.y)/room.height*100);
 try{drag.el.setPointerCapture(drag.pointerId);}catch{}
 toast('이동 준비! 끌어서 원하는 곳에 놓아주세요.');
}
document.addEventListener('pointerdown',event=>{
 if(page!=='room'||!$('#modal').classList.contains('hidden')||event.button!==0)return;
 const el=event.target.closest?.('[data-room-item]');if(!el){clearMoveReady();return;}
 const ready=moveReady===el;if(!ready)clearMoveReady();if(roomDrag)clearTimeout(roomDrag.timer);
 const drag={el,room:el.closest('.dust-room'),pointerId:event.pointerId,x:event.clientX,y:event.clientY,active:false,moved:false,initialLeft:el.style.left,initialTop:el.style.top};roomDrag=drag;
 if(ready)activateRoomDrag(drag);else drag.timer=setTimeout(()=>activateRoomDrag(drag),500);
},true);
document.addEventListener('pointermove',event=>{
 const d=roomDrag;if(!d||event.pointerId!==d.pointerId)return;
 if(!d.active){if(Math.hypot(event.clientX-d.x,event.clientY-d.y)>8){clearTimeout(d.timer);roomDrag=null;}return;}
 event.preventDefault();event.stopImmediatePropagation();rubTrack=null;
 if(Math.hypot(event.clientX-d.x,event.clientY-d.y)>2)d.moved=true;
 const room=d.room.getBoundingClientRect(),box=d.el.getBoundingClientRect(),padX=(box.width/2+8)/room.width*100,padY=(box.height/2+12)/room.height*100;
 const x=Math.max(padX,Math.min(100-padX,(event.clientX+d.offsetX-room.x)/room.width*100)),y=Math.max(padY,Math.min(100-padY,(event.clientY+d.offsetY-room.y)/room.height*100));
 setItemAnchor(d.el,x,y);const keeper=$('#adventureDoor');if(keeper&&d.el.dataset.roomItem==='dust')keeper.classList.toggle('drop-ready',insideKeeper(keeper.getBoundingClientRect(),event.clientX+d.offsetX,event.clientY+d.offsetY));
},true);
function finishRoomDrag(event,cancel=false){
 const d=roomDrag;if(!d||event.pointerId!==d.pointerId)return;clearTimeout(d.timer);roomDrag=null;
 if(!d.active)return;
 event.preventDefault();event.stopImmediatePropagation();rubTrack=null;suppressRoomClickUntil=Date.now()+700;suppressDustClickUntil=Date.now()+700;
 $('#adventureDoor')?.classList.remove('drop-ready');d.el.classList.remove('moving-item');try{if(d.el.hasPointerCapture(d.pointerId))d.el.releasePointerCapture(d.pointerId);}catch{}
 if(cancel){setItemAnchor(d.el,parseFloat(d.initialLeft),parseFloat(d.initialTop));d.el.style.animation='';clearMoveReady();return;}
 if(!d.moved)return;
 const keeper=$('#adventureDoor'),box=d.el.getBoundingClientRect();if(d.el.dataset.roomItem==='dust'&&keeper&&insideKeeper(keeper.getBoundingClientRect(),box.x+box.width/2,box.y+box.height/2)){const result=startAdventure(state,Number(d.el.dataset.roomId),state.keeperRoute);clearMoveReady();keeper.classList.remove('drop-ready');if(result.ok){save();render();toast('루미가 배웅했어요. '+find(QUESTS,state.keeperRoute).name+'으로 모험을 떠났어요.');return;}toast(result.message);}
 const r=moveRoomItem(state,d.el.dataset.roomItem,d.el.dataset.roomId,parseFloat(d.el.style.left),parseFloat(d.el.style.top));
 if(r.ok){setItemAnchor(d.el,r.position.x,r.position.y);d.el.classList.add('positioned');const gold=document.querySelector(`[data-gold-slot="${d.el.dataset.roomId}"]`);gold?.classList.add('positioned');save();toast('여기에 놓았어요. 위치를 기억할게요.');}
 clearMoveReady();d.el.style.animation='';
}
document.addEventListener('pointerup',e=>finishRoomDrag(e),true);
document.addEventListener('pointercancel',e=>finishRoomDrag(e,true),true);
document.addEventListener('contextmenu',e=>{if(e.target.closest?.('[data-room-item]'))e.preventDefault();});
document.addEventListener('keydown',event=>{
 if(event.key==='Escape'){if(roomDrag)finishRoomDrag({pointerId:roomDrag.pointerId,preventDefault(){},stopImmediatePropagation(){}},true);clearMoveReady();return;}
 const el=event.target.closest?.('[data-room-item]');if(!el||!event.altKey||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return;
 event.preventDefault();const x=parseFloat(el.style.left)+(event.key==='ArrowLeft'?-2:event.key==='ArrowRight'?2:0),y=parseFloat(el.style.top)+(event.key==='ArrowUp'?-2:event.key==='ArrowDown'?2:0),r=moveRoomItem(state,el.dataset.roomItem,el.dataset.roomId,x,y);
 if(r.ok){setItemAnchor(el,r.position.x,r.position.y);el.classList.add('positioned');save();}
});

function furnitureCard(f){const owned=state.ownedFurniture.includes(f.id),on=installed(state,f.id),lv=furnitureLevel(state,f.id),price=upgradeCost(state,f.id);return `<article class="furniture-card ${on?'placed':''}"><div class="furniture-picture" style="--furniture-color:${f.color}">${furnitureArt(f.id,lv||1)}<span>${on?'우리 방에 있어요':owned?'보관 중':'새로운 살림'} · Lv.${lv||1} / 5</span></div><div class="furniture-info"><span class="effect-badge">${furnitureEffect(state,f.id)}</span><h2>${f.name}</h2><div class="furniture-level-track" aria-label="가구 레벨 ${lv} / 5">${[1,2,3,4,5].map(n=>`<i class="${lv>=n?'lit':''}"></i>`).join('')}</div><p>${owned?FURNITURE_STORIES[f.id][lv-1][0]+' — '+(lv===5?'오래 함께한 이야기가 가득해요.':'더 포근하게 키우면 다음 이야기가 열려요.'):'처음 놓는 날, 이 가구의 첫 이야기가 시작돼요.'}</p>${owned?`<button class="button yellow full" data-upgrade-furniture="${f.id}" ${price===null||state.gold<price?'disabled':''}>${price===null?'Lv.5 · 가장 포근한 모습':price+' 골드 · Lv.'+(lv+1)+'로 업그레이드'}</button>`:''}<div class="furniture-toolbar"><button class="button secondary" data-furniture="${f.id}" ${!owned&&state.gold<f.price?'disabled':''}>${on?'넣어두기':owned?'다시 놓기':f.price+' 골드 · 사서 놓기'}</button><button class="text-button" data-furniture-story="${f.id}:${Math.max(0,lv-1)}">이야기 ${lv} / 5 ↗</button></div></div></article>`;}
function furnitureBook(id,index=0){const f=FURNITURE.find(x=>x.id===id);if(!f)return;const lv=furnitureLevel(state,id),i=Math.min(Math.max(index,0),Math.max(0,lv-1)),chapter=FURNITURE_STORIES[id][i];modal(f.name+'의 작은 이야기',`<div class="furniture-story-art" style="--furniture-color:${f.color}">${furnitureArt(id,lv||1)}</div><span class="new-badge">Lv.${lv} / 5 · ${furnitureEffect(state,id)}</span>${lv?`<h3 class="unlocked-story-title">${chapter[0]}</h3><p class="story-body">${chapter[1]}</p>`:'<p>아직 우리 방에 오지 않은 가구예요.<br>가구를 사서 놓으면 첫 이야기가 열려요.</p>'}<div class="furniture-chapters">${FURNITURE_STORIES[id].map((c,j)=>`<button data-furniture-story="${id}:${j}" ${j>=lv?'disabled':''} class="${i===j&&lv?'current':''}"><b>${j+1}</b><span>${j<lv?c[0]:'Lv.'+(j+1)+'에 열리는 이야기'}</span></button>`).join('')}</div><button class="button secondary full" data-page="shop">작은 상점으로 돌아가기 →</button>`);}

function roomListContent(){const current=ROOMS[state.roomLevel-1];return `<p class="rooms-intro">${current.name} · 방 ${homeCount(state)} / ${current.capacity}자리<br>보관함 ${storedCount(state)} / ${current.storage}자리 · 보유 골드 ${state.gold}<br><small>모험 중인 친구의 돌아올 자리도 남겨두어요.</small></p><div class="room-list">${ROOMS.map((room,i)=>{const done=i<state.roomLevel,next=i===state.roomLevel;return `<article class="room-option ${i===state.roomLevel-1?'current':''} ${next?'next':''}"><div class="room-miniature" style="--room-color:${room.color}"><span>⌂</span><small>Lv.${i+1}</small></div><div class="room-option-info"><span class="room-option-state">${i===state.roomLevel-1?'지금 우리 방':done?'함께 지낸 방':next?'다음으로 업그레이드할 방':'앞의 방부터 차례로 열려요'}</span><h3>${room.name}</h3><p>방 ${room.capacity}마리 · 보관 ${room.storage}마리 · 골드 +${room.bonus}%</p><div>${done?`<button class="text-button" data-room-story="${i+1}">이 방의 이야기 읽기 ↗</button>`:`<span class="room-upgrade-cost">${room.cost} 골드</span>`}${next?`<button class="button yellow" data-upgrade-room ${state.gold<room.cost?'disabled':''}>이 방으로 업그레이드</button>`:''}</div></div></article>`;}).join('')}</div>`;}
function openRooms(){modal('우리가 머무는 작은 방들.',`<div id="roomList">${roomListContent()}</div>`);roomDialogOpen=true;$('.modal-card').classList.add('rooms-dialog');}
function refreshRooms(){if(roomDialogOpen&&$('#roomList'))$('#roomList').innerHTML=roomListContent();}
function roomStory(index){if(index<0||index>=state.roomLevel||!ROOMS[index])return;const room=ROOMS[index];modal(room.storyTitle,`<div class="room-story-cover" style="--room-color:${room.color}"><span>⌂</span><b>Lv.${index+1} · ${room.name}</b></div><p class="story-body">${room.story}</p><button class="button secondary full" data-open-rooms>방 목록으로 돌아가기 →</button>`);}

function roomFairy(){return state.fairyOwned?`<button class="room-fairy" id="fairyCollect" aria-label="요정 모아 · 골드 모두 받기"><span class="fairy-aura" aria-hidden="true"></span>${icon('fairy')}<b>골드 모으는 모아</b><small id="fairyStatus">골드 모두 받기</small></button>`:'';}
